// ANALYTICS_MODEL_BEGIN
// Fictional source and event facts, separate from the editable board status.
const ANALYTICS_FACTS={};
const ANALYSIS_TYPES={"hh":"hh.ru","tg":"Telegram"};
const ANALYSIS_SOURCE_NAMES={"hh|hh.ru":"hh.ru","tg|чат продавцов":"Чат продавцов","tg|архив telegram":"Архив Telegram"};
const REPLY_CLASSES={
  warm:{name:'Тёплые — просят следующий шаг',color:'#4a8a61'},
  regular:{name:'Обычные ответы без интереса',color:'#91a08d'},
  hr:{name:'Зовут как кандидата',color:'#bd9d60'},
  thanks:{name:'Поблагодарил и ушёл',color:'#99a793'},
  no:{name:'Отказ',color:'#b87b72'},
  bot:{name:'Автоответ бота',color:'#7a9baa'},
  unclear:{name:'Не разобрано',color:'#a18eaa'}
};
function analysisReplyText(l){return String(l.semanticReplyText||'').trim();}
function analysisHasReply(l){return Boolean(analysisReplyText(l));}
function analysisWasSent(l){return Boolean(l.sentAt)||l.sent===true;}
function analysisReplyClass(l){return analysisHasReply(l)?(REPLY_CLASSES[l.replyClass]?l.replyClass:'unclear'):null;}
function analysisPercent(n,d){return d?Math.round(n/d*100)+'%':'—';}
function analysisEventDay(value){
  const raw=String(value||'');const match=raw.match(/^(\d{4}-\d{2}-\d{2})(?:$|T| )/);if(!match)return '';
  const day=match[1],check=new Date(day+'T12:00:00Z');if(!Number.isFinite(check.getTime())||check.toISOString().slice(0,10)!==day)return '';
  if(raw===day)return day;
  const d=new Date(raw.replace(' ','T'));if(!Number.isFinite(d.getTime()))return '';
  const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Moscow',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(d);
  return ['year','month','day'].map(t=>parts.find(p=>p.type===t).value).join('-');
}
function analysisFoundDay(l){return analysisEventDay(l.foundAt||l.foundDate||l.date);}
function analysisReplyAt(l){return l.replyAt||'';}
function analysisWarmAt(l){return l.warmAt||(analysisReplyClass(l)==='warm'?analysisReplyAt(l):'');}
function analysisReplyDays(l){return [...new Set([analysisReplyAt(l),l.latestReplyAt,l.firstReplyAt,l.replyFirst?.at,...(l.dialogue||[]).filter(m=>m.direction==='in').map(m=>m.at)].map(analysisEventDay).filter(Boolean))].sort();}
function analysisInRange(day,range={}){return day?(!range.from||day>=range.from)&&(!range.to||day<=range.to):!range.from&&!range.to;}
function analysisEventTime(value){const day=analysisEventDay(value);if(!day)return -Infinity;return Date.parse(String(value).length===10?day+'T00:00:00+03:00':String(value).replace(' ','T'));}
function analysisActivity(l){
  const events=[{at:l.foundAt||l.foundDate||l.date,label:'Найден'},{at:l.sentAt,label:'Отправлено'},{at:analysisReplyAt(l),label:'Ответ'},{at:l.latestReplyAt,label:'Последнее входящее'},{at:l.dialogue?.at(-1)?.at,label:'Сообщение'},{at:l.activityAt,label:'Обновлена карточка'}];
  return events.filter(e=>analysisEventDay(e.at)).sort((a,b)=>analysisEventTime(b.at)-analysisEventTime(a.at))[0]||{at:'',label:'Без даты'};
}
function analysisActivityDay(l){return analysisEventDay(analysisActivity(l).at);}
function analysisCohort(rows,range={}){return rows.filter(l=>analysisInRange(analysisFoundDay(l),range));}
function analysisRate(s){return s.sent&&!s.rateIncomplete?analysisPercent(s.cohortWarm,s.sent):'—';}
function previewBaseStats(rows,range={}){
  const blank=()=>Object.fromEntries(Object.keys(REPLY_CLASSES).map(k=>[k,0]));
  const result={found:0,sent:0,replied:0,warm:0,cohortWarm:0,last:'',classes:blank(),attributedClasses:blank(),undated:{found:0,sent:0,replied:0,warm:0},rateIncomplete:false};
  for(const l of rows){
    const found=Boolean(l.foundAt||l.foundDate||l.date),sent=analysisWasSent(l),type=analysisReplyClass(l);
    const replyDays=analysisReplyDays(l),fd=analysisFoundDay(l),sd=analysisEventDay(l.sentAt),rd=replyDays.filter(d=>analysisInRange(d,range)).at(-1)||replyDays.at(-1)||'',wd=analysisEventDay(analysisWarmAt(l));
    const fi=found&&analysisInRange(fd,range),si=sent&&analysisInRange(sd,range),ri=Boolean(type)&&(replyDays.length?replyDays.some(d=>analysisInRange(d,range)):analysisInRange('',range));
    if(found&&!fd)result.undated.found++;if(sent&&!sd)result.undated.sent++;
    if(type&&!rd){result.undated.replied++;if(type==='warm')result.undated.warm++;}
    if(fi)result.found++;if(si)result.sent++;
    if(ri){result.replied++;result.classes[type]++;}
    if(wd&&analysisInRange(wd,range))result.warm++;
    if(si&&(!sd||(type&&!rd)))result.rateIncomplete=true;
    if(si&&ri&&sd&&rd&&analysisEventTime(analysisReplyAt(l))>=analysisEventTime(l.sentAt)){
      result.attributedClasses[type]++;
    }
    if(si&&sd&&wd&&analysisInRange(wd,range)&&analysisEventTime(analysisWarmAt(l))>=analysisEventTime(l.sentAt))result.cohortWarm++;
    for(const day of [fi?fd:'',si?sd:'',ri?rd:'',analysisInRange(wd,range)?wd:''])if(day>result.last)result.last=day;
  }
  return result;
}
function analysisGroups(rows,range={}){
  return Object.entries(ANALYSIS_TYPES).map(([ch,name])=>{
    const members=rows.filter(l=>l.ch===ch),groups=new Map();
    for(const l of members){const key=analysisSourceKey(l);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(l);}
    const sources=[...groups].map(([key,items])=>({key,name:ANALYSIS_SOURCE_NAMES[ch+'|'+key]||(key==='unspecified'?'Источник не уточнён':String(items[0].src)),rows:items,stats:analysisStats(items,range)}));
    sources.sort((a,b)=>b.stats.warm-a.stats.warm||b.stats.found-a.stats.found||a.name.localeCompare(b.name,'ru'));
    return {ch,name,rows:members,stats:analysisStats(members,range),sources};
  });
}
function analysisHistory(rows,range={}){
  const foundRows=rows.filter(l=>(l.foundAt||l.foundDate||l.date)&&analysisInRange(analysisFoundDay(l),range));
  const days=[...new Set(foundRows.map(analysisFoundDay))].sort((a,b)=>a?(b?a.localeCompare(b):-1):1);
  const counts=items=>days.map(day=>items.filter(l=>analysisFoundDay(l)===day).length);
  return {days,total:foundRows.length,totals:counts(foundRows),groups:analysisGroups(foundRows).map(g=>({...g,counts:counts(g.rows),sources:g.sources.map(s=>({...s,counts:counts(s.rows)}))}))};
}
// ANALYTICS_MODEL_END

let analyticsTab='general';
const expandedHistoryTypes=new Set();
const ANALYTICS_TABS={general:'Общая аналитика',replies:'Аналитика ответов',sources:'Аналитика источников'};
function currentAnalyticsRows(){return leads;}
function analyticsMetric(label,value,note='',accent=false){return `<div class="analytics-metric ${accent?'accent':''}"><span>${label}</span><strong class="num">${value}</strong><small>${note}</small></div>`;}
function analyticsGeneral(rows){
  const s=analysisStats(rows,dateRange);
  return `<div class="analytics-kpis">${analyticsMetric('Найдено',s.found,'первые находки за период')}${analyticsMetric('Отправлено',s.sent,'отправки за период')}${analyticsMetric('Ответили',s.replied,'ответы за период')}${analyticsMetric('Тёплые',s.warm,'тёплые ответы за период',true)}${analyticsMetric('Тёплые по отправкам',analysisRate(s),s.rateIncomplete?'даты требуют проверки':s.sent?s.cohortWarm+' из '+s.sent+' отправок периода':'нет отправок за период',true)}</div><p class="analytics-caption">Доля: тёплые ответы за период на обращения, отправленные в этом же периоде, от числа этих отправок.</p>`;
}
function analyticsReplies(rows){
  const s=analysisStats(rows,dateRange);
  return `<section class="analytics-surface"><div class="analytics-section-head"><div><h3>Что стоит за ответами</h3><p>Тёплый ответ — просьба о следующем шаге. Последняя доля — только ответы на отправки этого же периода.</p></div><span class="analytics-quiet">Ответов: ${s.replied} · отправлено: ${s.sent}</span></div><div class="analytics-table-scroll"><table class="analytics-table reply-breakdown"><thead><tr><th>Категория ответа</th><th>Количество</th><th>Среди ответов</th><th>От отправок периода</th></tr></thead><tbody>${Object.entries(REPLY_CLASSES).map(([k,r])=>`<tr><th scope="row"><span class="reply-class-dot" style="background:${r.color}"></span>${r.name}</th><td>${s.classes[k]}</td><td>${analysisPercent(s.classes[k],s.replied)}</td><td>${s.rateIncomplete?'—':analysisPercent(s.attributedClasses[k],s.sent)}</td></tr>`).join('')}</tbody><tfoot><tr><th>Все ответы</th><td>${s.replied}</td><td>${analysisPercent(s.replied,s.replied)}</td><td>${s.rateIncomplete?'—':analysisPercent(Object.values(s.attributedClasses).reduce((a,b)=>a+b,0),s.sent)}</td></tr></tfoot></table></div></section>`;
}
function analyticsSourceCells(s){return [['Найдено',s.found],['Отправлено',s.sent],['Ответили',s.replied],['Тёплые',s.warm],['Тёплые по отправкам',analysisRate(s)],['Последнее событие',s.last?formatFoundDate(s.last):'—']].map(([label,value])=>`<span class="source-metric"><small>${label}</small><strong>${value}</strong></span>`).join('');}
function analyticsSources(rows){
  const groups=analysisGroups(rows,dateRange),total=analysisStats(rows,dateRange);
  return `<section class="analytics-surface"><div class="analytics-section-head"><div><h3>Откуда приходят лиды</h3><p>Тип источника и конкретные каналы. Доля тёплых — только по отправкам того же периода.</p></div><span class="analytics-quiet">Лидов: ${total.found} · тёплых: ${total.warm}</span></div><div class="analytics-source-groups">${groups.map(g=>`<details class="analytics-source-group" id="analytics-source-${g.ch}" ${g.ch==='tg'?'open':''}><summary><span class="source-group-name">${icon('chevron','sm')}<span class="source-tag ${g.ch}">${g.name}</span><small>${g.sources.length} ${g.sources.length===1?'подисточник':g.sources.length>1&&g.sources.length<5?'подисточника':'подисточников'}</small></span>${analyticsSourceCells(g.stats)}</summary><div class="source-group-content">${g.sources.length?`<div class="analytics-table-scroll"><table class="analytics-table subsource-table"><thead><tr><th>Канал / площадка</th><th>Найдено</th><th>Отправлено</th><th>Ответили</th><th>Тёплые</th><th>Тёплые по отправкам</th><th>Последнее событие</th></tr></thead><tbody>${g.sources.map(s=>`<tr data-subsource="${esc(g.ch+'|'+s.key)}"><th scope="row">${esc(s.name)}</th><td>${s.stats.found}</td><td>${s.stats.sent}</td><td>${s.stats.replied}</td><td>${s.stats.warm}</td><td>${analysisRate(s.stats)}</td><td>${s.stats.last?formatFoundDate(s.stats.last):'—'}</td></tr>`).join('')}</tbody></table></div>`:'<p class="analytics-empty-small">За выбранный период находок нет.</p>'}</div></details>`).join('')}</div><div class="analytics-source-total"><span>Все источники</span>${analyticsSourceCells(total)}</div></section>`;
}
function analyticsHistoryMarkup(rows){
  const h=analysisHistory(rows,dateRange);
  const dataCells=(counts,total,sub=false)=>counts.map(n=>`<td class="${n?'has-found':'zero'} ${sub?'sub-cell':''}">${n}</td>`).join('')+`<td class="history-total">${total}</td>`;
  return `<section class="analytics-surface analytics-history" id="analyticsHistory"><div class="analytics-section-head"><div><h3>История находок по дням</h3><p>Сколько новых клиентов найдено каждый день.</p></div><span class="analytics-quiet">Лидов: ${h.total}</span></div>${h.days.length?`<div class="analytics-table-scroll"><table class="analytics-table history-table" style="min-width:${Math.max(700,290+h.days.length*70)}px"><colgroup><col class="history-name-col">${h.days.map(()=>'<col>').join('')}<col></colgroup><thead><tr><th>Источник</th>${h.days.map(d=>`<th title="${esc(formatFoundDate(d))}">${d?new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(d+'T12:00:00Z')).replace('.',''):'Без даты'}</th>`).join('')}<th>Всего</th></tr></thead><tbody>${h.groups.map(g=>`<tr class="history-group-row"><th scope="row"><button class="history-group-button ${expandedHistoryTypes.has(g.ch)?'expanded':''}" data-history-type="${g.ch}" aria-expanded="${expandedHistoryTypes.has(g.ch)}" aria-label="Каналы в истории: ${g.name}">${icon('chevron','sm')}<span>${g.name}</span></button></th>${dataCells(g.counts,g.stats.found)}</tr>${expandedHistoryTypes.has(g.ch)?g.sources.map(s=>`<tr class="history-subsource-row" data-history-subsource="${esc(g.ch+'|'+s.key)}"><th scope="row">${esc(s.name)}</th>${dataCells(s.counts,s.stats.found,true)}</tr>`).join(''):''}`).join('')}</tbody><tfoot><tr><th>Все источники</th>${dataCells(h.totals,h.total)}</tr></tfoot></table></div>`:'<p class="analytics-empty-small">В выбранном периоде лидов нет.</p>'}</section>`;
}
function analyticsPanelMarkup(rows){return ({general:analyticsGeneral,replies:analyticsReplies,sources:analyticsSources}[analyticsTab]||analyticsGeneral)(rows);}
function analytics(){
  const rows=currentAnalyticsRows();
  return `<div class="analytics-page" role="region" aria-label="Аналитика"><div class="analytics-tabs" role="tablist" aria-label="Виды аналитики">${Object.entries(ANALYTICS_TABS).map(([key,label])=>`<button id="analytics-tab-${key}" role="tab" aria-selected="${key===analyticsTab}" aria-controls="analyticsPanel" class="${key===analyticsTab?'active':''}" data-analysis-tab="${key}">${label}</button>`).join('')}</div><div id="analyticsPanel" class="analytics-panel" role="tabpanel" aria-labelledby="analytics-tab-${analyticsTab}">${analyticsPanelMarkup(rows)}</div><div id="analyticsHistoryContainer" ${analyticsTab!=='general'?'hidden':''}>${analyticsHistoryMarkup(rows)}</div><p class="analytics-period-note">Находки, отправки и ответы — каждый по дате своего события. ${analyticsUndatedNote(rows)}</p></div>`;
}
function setAnalyticsTab(key){
  if(!ANALYTICS_TABS[key])return;analyticsTab=key;
  document.querySelectorAll('[data-analysis-tab]').forEach(b=>{const active=b.dataset.analysisTab===key;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active));});
  $('analyticsHistoryContainer').hidden=key!=='general';$('analyticsPanel').innerHTML=analyticsPanelMarkup(currentAnalyticsRows());$('analyticsPanel').setAttribute('aria-labelledby','analytics-tab-'+key);window.scrollTo({top:0});
}
function toggleAnalyticsHistory(ch){
  if(expandedHistoryTypes.has(ch))expandedHistoryTypes.delete(ch);else expandedHistoryTypes.add(ch);
  $('analyticsHistoryContainer').innerHTML=analyticsHistoryMarkup(currentAnalyticsRows());
  document.querySelector(`[data-history-type="${ch}"]`)?.focus();
}

const analysisSourceKey=function sourceKey(row){
  // The production builder appends the signal/date after a comma.
  const raw=String(row.src||'').split(',')[0].trim();
  const m=raw.match(/^(?:@|https?:\/\/(?:www\.)?t\.me\/)([a-z0-9_]+)\/?$/i);
  return (m?m[1]:raw||'unspecified').normalize('NFC').replace(/\s+/g,' ').toLocaleLowerCase('ru');
};


