async function workspaceRequest(action,body){
  if(REAL_PREVIEW.demo)return workspaceDemoRequest(action,body);
  if(!workspaceConnected)throw Error('Чтобы сохранить изменения, откройте кабинет на сайте и войдите через Telegram.');
  const r=await fetch(`/api/client/${encodeURIComponent(REAL_PREVIEW.client.id)}/${action}`,{method:body?'POST':'GET',credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},...(body?{body:JSON.stringify(body)}:{})});
  if(r.status===401)throw Error('Войдите в кабинет заново, чтобы продолжить.');
  const data=await r.json().catch(()=>({error:'Не удалось получить ответ. Обновите страницу.'}));
  if(!r.ok)throw Error(data.error||'Не удалось сохранить изменения');return data;
}
async function workspaceLoad(){
  if(!workspaceConnected)return;
  try{
    workspace=await workspaceRequest('state');workspaceReady=true;
    const stages=new Map((workspace.leadStages||[]).map(card=>[card.id,card]));for(const row of leads){const card=stages.get(String(row.id));if(card){row.cat=({DEC:'MOD',AI:'ARCH'})[card.cat]||card.cat;row.stageVersion=card.version;row.stageHistory=card.stageHistory;if(card.catAt)row.activityAt=card.catAt;}}
    const returnUrl=new URL(location.href);
    if(returnUrl.searchParams.get('paid')==='1'){
      page='payments';
      try{workspace=await workspaceRequest('billing/refresh',{});}catch(e){workspaceError(e);}
      returnUrl.searchParams.delete('paid');history.replaceState(null,'',returnUrl.pathname+returnUrl.search+returnUrl.hash);
    }
    renderPage();
  }
  catch(e){workspaceError(e);}
}
