async function workspaceDemoRequest(action,body){
  if(action==='stage'){const row=leads.find(row=>row.id===body.id);return {...workspace,card:{id:body.id,cat:body.cat,catAt:new Date().toISOString(),version:row.stageVersion,stageHistory:[...(row.stageHistory||[]),{from:row.cat,to:body.cat,at:new Date().toISOString()}]}};}
  if(action==='tone'){workspace.tone={...body.tone,examples:String(body.tone.examples||'').split(/\n\s*\n/)};return workspace;}
  if(action.startsWith('agents/')){const s=body.settings;workspace.agents[action.slice(7)]={rules:s.rules,sources:{own:s.own.split('\n'),exclude:s.exclude.split('\n'),note:s.note}};return workspace;}
  if(action==='chat'){workspace.chat.push({...body,role:'client',at:new Date().toISOString(),status:'answered'},{agent:body.agent,role:'agent',text:'Это пример диалога с агентом. В рабочем кабинете здесь появится ответ вашей команды.',at:new Date().toISOString()});return workspace;}
  if(action==='billing/pay'){workspace.billing={...workspace.billing,plan:body.plan,status:'active',has_method:true,autopay:true,methodTitle:'Демонстрационная карта •••• 4242',paid_until:new Date(Date.now()+30*86400000).toISOString()};return workspace;}
  if(action==='billing/unlink'){workspace.billing={...workspace.billing,has_method:false,autopay:false,methodTitle:null};return workspace;}
  return workspace;
}
